// Package httpapi implements the RESTful API generated by oapi-codegen.
//
// STEP 5 — Every HTTP handler translates the REST request into gRPC call(s),
// and the gRPC reply (or error) back into a REST response:
//
//	client --HTTP/JSON--> Handlers --gRPC--> AuctionService server (this node or a peer)
//
// Five REST operations share four RPCs:
//
//	GET    /v1/auctions                 -> Read (server stream of auctions)
//	POST   /v1/auctions/{auctionId}     -> CreateAuction (unary)
//	GET    /v1/auctions/{auctionId}     -> Read (server stream, 1 auction)
//	PATCH  /v1/auctions/{auctionId}     -> PlaceBid (unary RMW)
//	DELETE /v1/auctions/{auctionId}     -> CloseAuction (unary)
//
// Handlers hold NO application state. That is deliberate: in Parts II-III
// the gRPC target becomes "the server responsible for this request", which
// is exactly the forwarding required by the assignment.
package httpapi

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strconv"
	"strings"

	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	auctionv1 "github.com/your-team/auction/gen/auction/v1"
	"github.com/your-team/auction/gen/rest"
)

// Handlers implements rest.StrictServerInterface (one method per operationId).
type Handlers struct {
	KV auctionv1.AuctionServiceClient
}

// Compile-time check: the build fails here if a method is missing or has the
// wrong signature after you change openapi.yaml and regenerate.
var _ rest.StrictServerInterface = (*Handlers)(nil)

// NewHTTPHandler wires the strict handlers into a net/http mux.
func NewHTTPHandler(kv auctionv1.AuctionServiceClient, mux *http.ServeMux) http.Handler {
	strict := rest.NewStrictHandlerWithOptions(&Handlers{KV: kv}, nil, rest.StrictHTTPServerOptions{
		// Malformed requests (bad JSON, wrong parameter types) -> 400.
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeProblem(w, http.StatusBadRequest, err.Error())
		},
		// Errors returned by the handlers below (usually gRPC errors).
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			writeProblem(w, httpStatusFromGRPC(err), errorMessage(err))
		},
	})
	return rest.HandlerFromMux(strict, mux)
}

