// GET /v1/auctions?status=OPEN|CLOSED&consistency=sequential|linearizable
func (h *Handlers) ListAuctions(ctx context.Context, req rest.ListAuctionsRequestObject) (rest.ListAuctionsResponseObject, error) {
	in := &auctionv1.ReadRequest{
		Consistency: toProtoConsistency(req.Params.Consistency),
	}
	if req.Params.Status != nil {
		statusFilter, err := toProtoStatus(string(*req.Params.Status))
		if err != nil {
			return nil, err
		}
		in.Select = &auctionv1.ReadRequest_StatusFilter{
			StatusFilter: statusFilter,
		}
	}

	stream, err := h.KV.Read(ctx, in)
	if err != nil {
		return nil, err
	}
	auctions, err := recvAuctions(stream)
	if err != nil {
		return nil, err
	}
	return rest.ListAuctions200JSONResponse{Auctions: auctions}, nil
}

// POST /v1/auctions/{auctionId} — create a new auction.
func (h *Handlers) CreateAuction(ctx context.Context, req rest.CreateAuctionRequestObject) (rest.CreateAuctionResponseObject, error) {
	resp, err := h.KV.CreateAuction(ctx, &auctionv1.CreateAuctionRequest{
		AuctionId:     req.AuctionId,
		Item:          req.Body.Item,
		StartingPrice: req.Body.StartingPrice,
	})
	if err != nil {
		return nil, err // ALREADY_EXISTS -> 409, INVALID_ARGUMENT -> 400
	}
	a := resp.GetAuction()
	return rest.CreateAuction201JSONResponse{
		Body:    auctionFromProto(a),
		Headers: rest.CreateAuction201ResponseHeaders{ETag: ptr(etag(a.GetVersion()))},
	}, nil
}

// GET /v1/auctions/{auctionId} — read a single auction.
func (h *Handlers) GetAuction(ctx context.Context, req rest.GetAuctionRequestObject) (rest.GetAuctionResponseObject, error) {
	stream, err := h.KV.Read(ctx, &auctionv1.ReadRequest{
		Select:      &auctionv1.ReadRequest_AuctionId{AuctionId: req.AuctionId},
		Consistency: toProtoConsistency(req.Params.Consistency),
	})
	if err != nil {
		return nil, err
	}
	msg, err := stream.Recv()
	if err != nil {
		return nil, err // NOT_FOUND -> 404
	}
	a := msg.GetAuction()
	return rest.GetAuction200JSONResponse{
		Body:    auctionFromProto(a),
		Headers: rest.GetAuction200ResponseHeaders{ETag: ptr(etag(a.GetVersion()))},
	}, nil
}

// PATCH /v1/auctions/{auctionId} — place a bid (Read-Modify-Write).
func (h *Handlers) PlaceBid(ctx context.Context, req rest.PlaceBidRequestObject) (rest.PlaceBidResponseObject, error) {
	ifVersion, err := versionFromIfMatch(req.Params.IfMatch)
	if err != nil {
		return nil, err
	}
	resp, err := h.KV.PlaceBid(ctx, &auctionv1.PlaceBidRequest{
		AuctionId: req.AuctionId,
		Bidder:    req.Body.Bidder,
		Amount:    req.Body.Amount,
		IfVersion: ifVersion,
	})
	if err != nil {
		return nil, err // NOT_FOUND -> 404, ABORTED -> 409, FAILED_PRECONDITION -> 412
	}
	a := resp.GetAuction()
	return rest.PlaceBid200JSONResponse{
		Body:    auctionFromProto(a),
		Headers: rest.PlaceBid200ResponseHeaders{ETag: ptr(etag(a.GetVersion()))},
	}, nil
}

// DELETE /v1/auctions/{auctionId} — close an auction.
func (h *Handlers) CloseAuction(ctx context.Context, req rest.CloseAuctionRequestObject) (rest.CloseAuctionResponseObject, error) {
	ifVersion, err := versionFromIfMatch(req.Params.IfMatch)
	if err != nil {
		return nil, err
	}
	resp, err := h.KV.CloseAuction(ctx, &auctionv1.CloseAuctionRequest{
		AuctionId: req.AuctionId,
		IfVersion: ifVersion,
	})
	if err != nil {
		return nil, err // NOT_FOUND -> 404, ABORTED -> 409, FAILED_PRECONDITION -> 412
	}
	a := resp.GetAuction()
	return rest.CloseAuction200JSONResponse{
		Body:    auctionFromProto(a),
		Headers: rest.CloseAuction200ResponseHeaders{ETag: ptr(etag(a.GetVersion()))},
	}, nil
}

// ---------------------------------------------------------------------------
// Streams & Helpers: REST <-> protobuf conversions and error mapping
// ---------------------------------------------------------------------------

// recvAuctions reads a Read server stream to the end.
func recvAuctions(stream auctionv1.AuctionService_ReadClient) ([]rest.Auction, error) {
	auctions := []rest.Auction{} // serialize as [] rather than null
	for {
		msg, err := stream.Recv()
		if errors.Is(err, io.EOF) {
			return auctions, nil
		}
		if err != nil {
			return nil, err
		}
		auctions = append(auctions, auctionFromProto(msg.GetAuction()))
	}
}

func auctionFromProto(a *auctionv1.Auction) rest.Auction {
	out := rest.Auction{
		AuctionId:  a.GetAuctionId(),
		Item:       a.GetItem(),
		CurrentBid: a.GetCurrentBid(),
		Status:     statusFromProto(a.GetStatus()),
		Version:    a.GetVersion(),
	}
	if a.HighestBidder != nil {
		b := a.GetHighestBidder()
		out.HighestBidder = &b
	}
	return out
}

func statusFromProto(s auctionv1.AuctionStatus) rest.AuctionStatus {
	if s == auctionv1.AuctionStatus_AUCTION_STATUS_CLOSED {
		return rest.CLOSED
	}
	return rest.OPEN
}

func toProtoStatus(s string) (auctionv1.AuctionStatus, error) {
	switch strings.ToUpper(s) {
	case "OPEN":
		return auctionv1.AuctionStatus_AUCTION_STATUS_OPEN, nil
	case "CLOSED":
		return auctionv1.AuctionStatus_AUCTION_STATUS_CLOSED, nil
	default:
		return auctionv1.AuctionStatus_AUCTION_STATUS_UNSPECIFIED,
			status.Errorf(codes.InvalidArgument, "invalid auction status %q", s)
	}
}

func toProtoConsistency[T ~string](c *T) auctionv1.Consistency {
	if c != nil && string(*c) == "linearizable" {
		return auctionv1.Consistency_CONSISTENCY_LINEARIZABLE
	}
	return auctionv1.Consistency_CONSISTENCY_SEQUENTIAL
}

// An ETag is the version in quotes, e.g. "3".
func etag(version int64) string { return strconv.Quote(strconv.FormatInt(version, 10)) }

// versionFromIfMatch parses an If-Match header; nil means "no condition".
func versionFromIfMatch(h *string) (*int64, error) {
	if h == nil || *h == "" {
		return nil, nil
	}
	s := strings.Trim(strings.TrimPrefix(*h, "W/"), `"`)
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return nil, status.Errorf(codes.InvalidArgument, "If-Match %q is not a version", *h)
	}
	return &v, nil
}

func ptr[T any](v T) *T { return &v }

// httpStatusFromGRPC is the single place where gRPC status codes become HTTP
// status codes. Keep it consistent with the responses in openapi.yaml.
func httpStatusFromGRPC(err error) int {
	if _, ok := status.FromError(err); !ok {
		if errors.Is(err, context.DeadlineExceeded) {
			return http.StatusGatewayTimeout
		}
		return http.StatusInternalServerError
	}
	switch status.Code(err) {
	case codes.NotFound:
		return http.StatusNotFound // 404
	case codes.InvalidArgument:
		return http.StatusBadRequest // 400
	case codes.AlreadyExists, codes.Aborted:
		return http.StatusConflict // 409
	case codes.FailedPrecondition:
		return http.StatusPreconditionFailed // 412: If-Match / ifVersion differs
	case codes.Unimplemented:
		return http.StatusNotImplemented // 501
	case codes.Unavailable:
		return http.StatusServiceUnavailable // 503
	case codes.DeadlineExceeded:
		return http.StatusGatewayTimeout // 504
	default:
		return http.StatusInternalServerError // 500
	}
}

func errorMessage(err error) string {
	if st, ok := status.FromError(err); ok {
		return st.Message()
	}
	return err.Error()
}

// writeProblem writes an RFC 9457 problem-details body.
func writeProblem(w http.ResponseWriter, code int, detail string) {
	w.Header().Set("Content-Type", "application/problem+json")
	w.WriteHeader(code)
	_ = json.NewEncoder(w).Encode(rest.ProblemDetails{
		Title:  http.StatusText(code),
		Status: int32(code),
		Detail: &detail,
	})
}
